<?php require __DIR__.'/bootstrap.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $subject=trim($_POST['subject']??'');$message=trim($_POST['message']??''); if($subject===''||$message===''){exit('Subject and feedback are required.');} $s=$pdo->prepare('INSERT INTO feedback(user_id,subject,message) VALUES(?,?,?)');$s->execute([user()['id'],$subject,$message]);log_action($pdo,'feedback_submitted',$subject);header('Location:feedback.php?sent=1');exit; }
$s=$pdo->prepare('SELECT * FROM feedback WHERE user_id=? ORDER BY created_at DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();page_top('Feedback'); ?><h1>Feedback</h1><?php if(isset($_GET['sent'])):?><p class="success">Thanks - your feedback was submitted.</p><?php endif; ?><section class="grid two"><form class="panel form-grid" method="post"><h2>Send feedback</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="full">Subject<input required name="subject" maxlength="180"></label><label class="full">Message<textarea required name="message" rows="6"></textarea></label><button>Submit feedback</button></form><div class="panel"><h2>Your submissions</h2><?php foreach($rows as $r): ?><article class="item"><h3><?=e($r['subject'])?> <span class="badge"><?=e($r['status'])?></span></h3><p><?=e($r['message'])?></p><small><?=date('d M Y',strtotime($r['created_at']))?></small></article><?php endforeach; if(!$rows) echo '<p class="muted">You have not submitted feedback yet.</p>'; ?></div></section><?php page_bottom();
